const aIAgentSlotClaim = `-- name: AIAgentSlotClaim :one
INSERT INTO ai_agent_slots (user_id, workspace_id, slot, run_id, lease_id, expires_at)
SELECT $1, $2, s, $3, $4, $5 FROM generate_series(1, 2) s
WHERE NOT EXISTS (SELECT 1 FROM ai_agent_slots WHERE workspace_id = $2 AND slot = s)
ORDER BY s LIMIT 1 ON CONFLICT DO NOTHING RETURNING user_id, workspace_id, slot, run_id, lease_id, expires_at
`

