const aIAgentSlotsExpire = `-- name: AIAgentSlotsExpire :exec
DELETE FROM ai_agent_slots WHERE user_id IN (
    SELECT s.user_id FROM ai_agent_slots s WHERE s.expires_at <= $1
    ORDER BY s.user_id FOR UPDATE SKIP LOCKED
)
`

// Never wait for another workspace's in-flight slot while holding this
// workspace's connection lock. Unique constraints arbitrate claims.
func (q *Queries) AIAgentSlotsExpire(ctx context.Context, now time.Time) error {
	_, err := q.db.Exec(ctx, aIAgentSlotsExpire, now)
	return err
}

